 void show(){show(section,"");}void show(int selected,String term){section=a.viewerKids?0:selected;query=term;page=0;a.page("profile","","",3,null);a.body.setPadding(a.dp(16),a.dp(4),a.dp(16),a.dp(10));replaceHeader();identity();EditText search=a.field(a.body,"","Buscar ferramenta",false);search.setTextSize(14);search.setPadding(a.dp(44),a.dp(12),a.dp(14),a.dp(12));LinearLayout.LayoutParams searchSize=(LinearLayout.LayoutParams)search.getLayoutParams();searchSize.height=a.dp(46);searchSize.bottomMargin=a.dp(10);search.setLayoutParams(searchSize);int searchIndex=a.body.indexOfChild(search);a.body.removeView(search);FrameLayout searchFrame=new FrameLayout(a);searchFrame.addView(search,new FrameLayout.LayoutParams(-1,-1));AppGlyph glass=new AppGlyph(a,"search",MUTED);FrameLayout.LayoutParams glassSize=new FrameLayout.LayoutParams(a.dp(21),a.dp(21),Gravity.LEFT|Gravity.CENTER_VERTICAL);glassSize.leftMargin=a.dp(14);searchFrame.addView(glass,glassSize);a.body.addView(searchFrame,searchIndex,searchSize);search.setText(term);search.setCompoundDrawablePadding(a.dp(8));LinearLayout tabs=a.row();String[] labels={"Biblioteca","Estúdio","Conta"};for(int i=0;i<labels.length;i++){final int n=i;LinearLayout tab=a.col();tab.setGravity(Gravity.CENTER);TextView t=a.label(labels[i],14,i==section?WHITE:MUTED);t.setGravity(Gravity.CENTER);t.setTypeface(android.graphics.Typeface.create("sans-serif-medium",0));tab.addView(t,new LinearLayout.LayoutParams(-1,a.dp(40)));View underline=new View(a);underline.setBackground(a.bg(i==section?RED:LINE,2));tab.addView(underline,new LinearLayout.LayoutParams(-1,a.dp(i==section?3:1)));tabs.addView(tab,new LinearLayout.LayoutParams(0,a.dp(44),1));tab.setContentDescription("Área "+labels[i]);tab.setOnClickListener(v->show(n,""));if(a.viewerKids&&i>0)tab.setVisibility(View.GONE);}a.body.addView(tabs);a.gap(a.body,16);LinearLayout caption=a.row();heading=a.label(labels[section],21,WHITE);heading.setTypeface(Typeface.DEFAULT_BOLD);caption.addView(heading,new LinearLayout.LayoutParams(0,-2,1));TextView customize=a.label("Personalizar",13,RED);customize.setPadding(a.dp(8),a.dp(10),0,a.dp(10));caption.addView(customize);customize.setOnClickListener(v->customize());a.body.addView(caption);a.gap(a.body,9);grid=a.col();a.body.addView(grid);render();status=a.label("",12,MUTED);status.setVisibility(View.GONE);a.body.addView(status);if((a.role.equals("admin")||!bootstrap.optString("staff").isEmpty())&&!a.viewerKids)adminEntry();search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int af){}public void afterTextChanged(Editable e){}public void onTextChanged(CharSequence s,int st,int before,int count){query=s.toString();page=0;render();}});a.call("GET","/v8/bootstrap?section="+section,null,r->{bootstrap=r;if(!r.optBoolean("workspace",true)){a.legacyProfile();return;}if(!a.viewerKids&&!r.optString("staff").isEmpty()&&a.body.findViewWithTag("workspace-admin")==null)adminEntry();JSONArray shortcuts=r.optJSONArray("shortcuts");if(shortcuts!=null)a.prefs.edit().putString(a.local("shortcuts_"+section),shortcuts.toString()).apply();int pending=r.optInt("pending_reviews")+r.optInt("open_tickets");int failed=0;JSONArray uploads=a.uploads.rows();for(int i=0;i<uploads.length();i++)if(uploads.optJSONObject(i).optString("status").startsWith("failed"))failed++;if(pending+failed>0){status.setText((pending>0?pending+" pendência(s) na conta":"")+(failed>0?" · "+failed+" envio(s) precisam de atenção":""));status.setVisibility(View.VISIBLE);}render();});}
 void replaceHeader(){ViewGroup header=(ViewGroup)a.root.getChildAt(0);if(header.getChildCount()>0)header.removeViewAt(header.getChildCount()-1);FrameLayout target=new FrameLayout(a);target.setContentDescription("Preferências da conta");AppGlyph icon=new AppGlyph(a,"gear",WHITE);FrameLayout.LayoutParams ip=new FrameLayout.LayoutParams(a.dp(24),a.dp(24),Gravity.CENTER);target.addView(icon,ip);header.addView(target,new LinearLayout.LayoutParams(a.dp(44),a.dp(36)));target.setOnClickListener(v->preferences());}
 void identity(){LinearLayout row=a.row();row.setPadding(0,a.dp(10),0,a.dp(10));String name=!a.viewerName.isEmpty()?a.viewerName:a.displayName();if(name.equals("Criador")||name.equals("Criador independente"))name="Seu perfil";TextView avatar=a.label(name.substring(0,1).toUpperCase(),22,WHITE);avatar.setTypeface(Typeface.DEFAULT_BOLD);avatar.setGravity(Gravity.CENTER);avatar.setBackground(a.bg(0xff243240,40));FrameLayout photo=new FrameLayout(a);photo.setBackground(a.bg(0xff243240,40));photo.setClipToOutline(true);photo.addView(avatar,new FrameLayout.LayoutParams(-1,-1));String raw=a.prefs.getString(a.local("avatar"),"");if(!raw.isEmpty()&&!a.viewerKids)try{byte[] bytes=android.util.Base64.decode(raw,2);ImageView image=new ImageView(a);image.setImageBitmap(BitmapFactory.decodeByteArray(bytes,0,bytes.length));image.setScaleType(ImageView.ScaleType.CENTER_CROP);photo.addView(image,new FrameLayout.LayoutParams(-1,-1));}catch(Exception ignored){}row.addView(photo,new LinearLayout.LayoutParams(a.dp(48),a.dp(48)));LinearLayout text=a.col();text.setPadding(a.dp(12),0,a.dp(8),0);TextView title=a.label(name,18,WHITE);title.setTypeface(Typeface.DEFAULT_BOLD);title.setMaxLines(1);title.setEllipsize(TextUtils.TruncateAt.END);text.addView(title);TextView edit=a.label(a.viewerKids?"Perfil infantil":"Editar perfil",13,0xffc4cfdd);edit.setPadding(0,a.dp(4),0,0);text.addView(edit);row.addView(text,new LinearLayout.LayoutParams(0,-2,1));text.setOnClickListener(v->{if(!a.viewerKids)a.pro.profileEditor();});FrameLayout swap=new FrameLayout(a);swap.addView(new AppGlyph(a,"switch",WHITE),new FrameLayout.LayoutParams(a.dp(27),a.dp(27),Gravity.CENTER));row.addView(swap,new LinearLayout.LayoutParams(a.dp(44),a.dp(44)));swap.setContentDescription("Trocar perfil de espectador");swap.setOnClickListener(v->a.accounts.profiles());a.body.addView(row);}
 String normalize(String s){return java.text.Normalizer.normalize(s.toLowerCase(new Locale("pt","BR")),java.text.Normalizer.Form.NFD).replaceAll("\\p{M}","");}
 boolean matches(String text,String query){for(String part:query.split(" +"))if(!text.contains(part))return false;return true;}
 void render(){if(grid==null)return;grid.removeAllViews();ArrayList<Tool> all=tools(),found=new ArrayList<>();String term=normalize(query.trim());String area=new String[]{"Biblioteca","Estúdio","Conta"}[section];JSONArray saved=new JSONArray();try{saved=new JSONArray(a.prefs.getString(a.local("shortcuts_"+section),"[]"));}catch(Exception ignored){}if(term.isEmpty()){for(int i=0;i<saved.length();i++)for(Tool t:all)if(t.id.equals(saved.optString(i)))found.add(t);if(found.isEmpty())for(Tool t:all)if(t.area.equals(area))found.add(t);}else{heading.setText("Ferramentas");for(Tool t:all)if(term.equals("*")||matches(normalize(t.title+" "+t.sub+" "+t.aliases),term))found.add(t);}if(term.isEmpty())heading.setText(area);if(found.isEmpty()){a.empty(grid,"search","Nenhuma ferramenta encontrada","Tente palavras como senha, downloads ou episódios.");return;}int start=page*6;for(int i=start;i<Math.min(start+6,found.size());i+=2){LinearLayout row=a.row();row.setGravity(Gravity.TOP);for(int j=i;j<Math.min(i+2,found.size());j++){Tool t=found.get(j);LinearLayout tile=a.col();tile.setPadding(a.dp(13),a.dp(10),a.dp(10),a.dp(9));tile.setBackground(a.outline(CARD,12));tile.addView(new AppGlyph(a,t.icon,WHITE),new LinearLayout.LayoutParams(a.dp(24),a.dp(24)));a.gap(tile,5);TextView title=a.label(t.title,14,WHITE);title.setTypeface(Typeface.DEFAULT_BOLD);title.setMaxLines(2);title.setEllipsize(TextUtils.TruncateAt.END);tile.addView(title);TextView sub=a.label(t.sub,11,0xffb6c5d7);sub.setPadding(0,a.dp(4),0,0);sub.setMaxLines(1);sub.setEllipsize(TextUtils.TruncateAt.END);tile.addView(sub);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,a.dp(a.getResources().getConfiguration().fontScale>1.15f?110:84),1);p.setMargins(0,0,j==i?a.dp(10):0,a.dp(8));row.addView(tile,p);tile.setContentDescription(t.title+". "+t.sub);tile.setOnClickListener(v->{if(!a.busy)t.run.run();});}if(i+1>=found.size())row.addView(new View(a),new LinearLayout.LayoutParams(0,1,1));grid.addView(row);}if(found.size()>6){LinearLayout pages=a.row();if(page>0)a.button(pages,"Anterior",CARD,()->{page--;render();}).setLayoutParams(new LinearLayout.LayoutParams(0,a.dp(44),1));if((page+1)*6<found.size())a.button(pages,"Mais ferramentas",CARD,()->{page++;render();}).setLayoutParams(new LinearLayout.LayoutParams(0,a.dp(44),1));grid.addView(pages);}}
 void adminEntry(){LinearLayout entry=a.row();entry.setTag("workspace-admin");entry.setPadding(a.dp(14),a.dp(12),a.dp(14),a.dp(12));entry.setBackground(a.outline(CARD,12));entry.addView(new AppGlyph(a,"shield",WHITE),new LinearLayout.LayoutParams(a.dp(26),a.dp(26)));LinearLayout text=a.col();text.setPadding(a.dp(14),0,0,0);TextView t=a.label("Administração",15,WHITE);t.setTypeface(Typeface.DEFAULT_BOLD);text.addView(t);text.addView(a.label("Controle da plataforma",11,MUTED));entry.addView(text,new LinearLayout.LayoutParams(0,-2,1));entry.addView(new AppGlyph(a,"arrow",WHITE),new LinearLayout.LayoutParams(a.dp(17),a.dp(17)));a.body.addView(entry,new LinearLayout.LayoutParams(-1,a.dp(62)));entry.setOnClickListener(v->a.moderationDesk.home());}
 void customize(){ArrayList<Tool> all=tools();String[] labels=new String[all.size()];boolean[] chosen=new boolean[all.size()];String area=new String[]{"Biblioteca","Estúdio","Conta"}[section];JSONArray saved;try{saved=new JSONArray(a.prefs.getString(a.local("shortcuts_"+section),"[]"));}catch(Exception e){saved=new JSONArray();}for(int i=0;i<all.size();i++){labels[i]=all.get(i).title;chosen[i]=saved.length()==0?all.get(i).area.equals(area):saved.toString().contains('"'+all.get(i).id+'"');}new AlertDialog.Builder(a).setTitle("Escolha até seis atalhos").setMultiChoiceItems(labels,chosen,(d,n,on)->chosen[n]=on).setNegativeButton("Cancelar",null).setPositiveButton("Salvar",(d,n)->a.safe(()->{JSONArray ids=new JSONArray();for(int i=0;i<chosen.length;i++)if(chosen[i])ids.put(all.get(i).id);if(ids.length()>6||ids.length()==0){Toast.makeText(a,"Escolha entre um e seis atalhos.",0).show();return;}a.prefs.edit().putString(a.local("shortcuts_"+section),ids.toString()).apply();a.socialRequest("POST","/v8/preferences",a.obj("section",section,"shortcuts",ids),r->{bootstrap=r;});render();})).show();}
